// PublicEventUserLocaleChanged Payload for user_locale.changed — a member chose the language their own interface is rendered in (identity/userlocale.go's SaveMyLocale). It is a change to the member's own seat rather than to anything the installation is measured in: the language AI writes for the whole team is the installation's base_language, which is an admin setting and publishes separately. A subscriber that renders anything for this contact needs to know which catalog to reach for.
type PublicEventUserLocaleChanged struct {
	// Locale The language now chosen — one of the catalogs the product ships. Never empty: this event fires on a choice, and a member who has never chosen has no row and produces no event.
	Locale string `json:"locale"`
}

// PublicEventUserMfaRemoved Payload for user.mfa_removed. An admin removed a member's confirmed second factor. Every session the member held ended with it. The password alone opens the account until the member sets a factor up again. So `by` and `user_id` are both required: this event records who weakened which sign-in.
type PublicEventUserMfaRemoved struct {
	// By The admin who removed it.
	By openapi_types.UUID `json:"by"`

	// SessionsEnded How many live sessions of the member the removal ended.
	SessionsEnded int `json:"sessions_ended"`

	// UserId The member whose second factor was removed.
	UserId openapi_types.UUID `json:"user_id"`
}

// PublicEventUserPasswordLinkIssued Payload for user.password_link_issued. On an installation with no outbound-email channel, an admin minted a single-use set-password link for a member (ADR-0061). The admin delivers it out-of-band. Issuing supersedes the target's outstanding unused tokens. The link may be minted for a member who already has a password. That is an account takeover an admin is trusted to perform. This event is the detective control that records it, so `by` and `user_id` are both required and are the point of the event. The token itself is never a property here, and must never be added. The raw value is returned to the issuing admin once, over the response body, and reaches no ledger, log or bus.
type PublicEventUserPasswordLinkIssued struct {
	// By The admin who issued the link.
	By openapi_types.UUID `json:"by"`

	// ExpiresAt When the single-use token stops being redeemable.
	ExpiresAt time.Time `json:"expires_at"`

	// UserId The member the link was minted for.
	UserId openapi_types.UUID `json:"user_id"`
}

// PublicEventUserReactivated Payload for user.reactivated. A deactivated member was lifted out of deactivation (identity/users.go's ReactivateUser). The `status` field says what they were returned to, and it is not always `active`. A member deactivated before redeeming their invitation comes back `invited`. They still hold no password and still sign in nowhere. A subscriber that assumed "reactivated means active" would restate the falsehood the invited status exists to remove.
type PublicEventUserReactivated struct {
	// By The admin who reactivated the member.
	By openapi_types.UUID `json:"by"`

	// Status The status a reactivated member was restored to.
	// It is not always `active`, which is the whole reason it travels: a member deactivated before redeeming their invitation comes back `invited`, because they still hold no password and still sign in nowhere. A subscriber that read the event type alone would record somebody as able to sign in who cannot.
	Status UserReactivatedStatus `json:"status"`

	// UserId The reactivated member.
	UserId openapi_types.UUID `json:"user_id"`
}

// PublicEventUserUpdated defines model for PublicEventUserUpdated.
type PublicEventUserUpdated struct {
	By     openapi_types.UUID `json:"by"`
	UserId openapi_types.UUID `json:"user_id"`
}

// PublicEventVoiceBuildChanged Payload for voice.build_changed. A Voice DNA build was queued, or an already-pending one was returned in place of a duplicate request (ai/voice_lifecycle.go's RequestBuild). The stage, result_version, status_code and next_attempt_at fields describe an in-flight or deferred build. So they are absent on a freshly queued one.
type PublicEventVoiceBuildChanged struct {
	// BuildId The build row.
	BuildId openapi_types.UUID `json:"build_id"`

	// CandidateAction The recommended next step for this build's candidate.
	CandidateAction string `json:"candidate_action"`

	// NextAttemptAt When a deferred build will next be attempted (absent unless deferred).
	NextAttemptAt *time.Time `json:"next_attempt_at,omitempty"`

	// ProfileId The profile this build belongs to.
	ProfileId openapi_types.UUID `json:"profile_id"`

	// Reason The human-approved reason for this build (onboarding | manual).
	Reason string `json:"reason"`

	// ResultVersion The profile version this build produced (absent until the build completes).
	ResultVersion *int `json:"result_version,omitempty"`

	// SourceCount The corpus's eligible source count this build was requested against.
	SourceCount int `json:"source_count"`

	// SourceHash The corpus content hash this build was requested against.
	SourceHash string `json:"source_hash"`

	// Stage The build's current pipeline stage (absent before it starts running).
	Stage *string `json:"stage,omitempty"`

	// Status The build's status, one of queued | deferred | running | succeeded | failed. These are the values voice_build_run.go persists and emits. The success terminal is "succeeded", not "completed".
	Status string `json:"status"`

	// StatusCode A machine-readable status detail code (absent unless the build failed or deferred).
	StatusCode *string `json:"status_code,omitempty"`
}

// PublicEventVoiceCorpusChanged Payload for voice.corpus_changed. It is a union across four emit sites that all mutate the corpus feeding a profile's build. A source's inclusion or weight was updated (voice_source_mutations.go's recordSourceUpdate). A source was removed (RemoveSource). A source was ingested or re-ingested (voice_source_store.go's recordSourceIngest). Or the whole corpus was cleared (voice_source_mutations.go's ClearCorpus). The source_id, origin and register fields name the touched source. So they are absent on the clear site, which acts on the corpus as a whole.
type PublicEventVoiceCorpusChanged struct {
	// Action What happened to the corpus. It is ingested (a new source was added) or replaced (an existing source was re-ingested). The other values are included, excluded, removed and cleared. These are the values the emit sites stamp (voice_source_store.go sourceIngestChange, voice_source_mutations.go sourceInclusionChange / ClearCorpus).
	Action string `json:"action"`

	// Origin The touched source's origin (manual | capture) (absent on the clear site).
	Origin *string `json:"origin,omitempty"`

	// ProfileId The profile whose corpus changed.
	ProfileId openapi_types.UUID `json:"profile_id"`

	// Register The touched source's register (email | social | long_form | spoken | general) (absent on the clear site).
	Register *string `json:"register,omitempty"`

	// SourceCount The corpus's eligible source count after this event.
	SourceCount int `json:"source_count"`

	// SourceHash The corpus's content hash after this event.
	SourceHash string `json:"source_hash"`

	// SourceId The source this event touched (absent on the clear site, which has no single source).
	SourceId *openapi_types.UUID `json:"source_id,omitempty"`

	// WordDelta The eligible-word-count change this action caused (may be negative).
	WordDelta int `json:"word_delta"`
}

// PublicEventVoiceDraftOutcomeRecorded Payload for voice.draft_outcome_recorded — a drafted-with-voice signal's outcome was recorded (ai/voice_history.go's RecordDraftOutcome), feeding the automatic-learning corpus.
type PublicEventVoiceDraftOutcomeRecorded struct {
	// Outcome The recorded outcome (drafted | sent_unedited | sent_edited | rejected).
	Outcome string `json:"outcome"`

	// ProfileId The profile this learning signal belongs to.
	ProfileId openapi_types.UUID `json:"profile_id"`

	// QualifiesAsSource Whether this draft's final text qualifies as a future corpus source.
	QualifiesAsSource bool `json:"qualifies_as_source"`

	// TransformationCount How many transformation edits were applied before send (0 for rejected).
	TransformationCount int `json:"transformation_count"`
}

// PublicEventVoiceProfileArchived Payload for voice.profile_archived — the owner's profile was soft-deleted (ai/voice.go's ArchiveProfile).
type PublicEventVoiceProfileArchived struct {
	// OwnerId The human who owned this profile.
	OwnerId openapi_types.UUID `json:"owner_id"`

	// ProfileId The archived profile.
	ProfileId openapi_types.UUID `json:"profile_id"`

	// ProfileVersion The profile's derived-artifact version at the moment it was archived.
	ProfileVersion int `json:"profile_version"`
}

// PublicEventVoiceProfileCreated Payload for voice.profile_created — the admitted human opened their one personal Voice DNA profile (ai/voice.go's CreateProfile). Always starts collecting, at maturity zero, with automatic learning off.
type PublicEventVoiceProfileCreated struct {
	// AutoLearningEnabled Whether automatic learning starts enabled (always false at creation).
	AutoLearningEnabled bool `json:"auto_learning_enabled"`

	// Maturity The corpus maturity band at creation (collecting, at zero words).
	Maturity string `json:"maturity"`

	// OwnerId The human who owns this profile.
	OwnerId openapi_types.UUID `json:"owner_id"`

	// ProfileId The created profile.
	ProfileId openapi_types.UUID `json:"profile_id"`
}

// PublicEventVoiceProfileUpdated Payload for voice.profile_updated — the owner replaced their human-authored preferences and/or their automatic-learning opt-in (ai/voice.go's UpdateProfile). action names which of the two (or both) this update touched.
type PublicEventVoiceProfileUpdated struct {
	// Action What this update did (preferences_replaced | learning_enabled | learning_disabled).
	Action string `json:"action"`

	// Maturity The corpus maturity band as of this update.
	Maturity string `json:"maturity"`

	// ProfileId The updated profile.
	ProfileId openapi_types.UUID `json:"profile_id"`

	// Version The profile row's optimistic-concurrency version after this update.
	Version int64 `json:"version"`
}

// PublicEventVoiceVersionChanged Payload for voice.version_changed — a derived Voice DNA version's status changed: minted as a candidate, manually activated, rejected, or restored by rollback (ai/voice_versions.go). predecessor_version is absent for a profile's first version, which has none.
type PublicEventVoiceVersionChanged struct {
	// ActivationOutcome What happened to this version (auto_activated | manually_activated | rejected | rollback).
	ActivationOutcome string `json:"activation_outcome"`

	// Classification The delta's classification against its predecessor (routine | material).
	Classification string `json:"classification"`

	// PredecessorVersion The version this one supersedes (absent for a profile's first version).
	PredecessorVersion *int `json:"predecessor_version,omitempty"`

	// ProfileId The profile this version belongs to.
	ProfileId openapi_types.UUID `json:"profile_id"`

	// ProfileVersion This version's number.
	ProfileVersion int `json:"profile_version"`

	// Reason Why this version was produced (e.g. build | rollback).
	Reason string `json:"reason"`

	// Status The version's status after this event (candidate | active | superseded | rejected).
	Status string `json:"status"`
}

// PublicEventWeeklyPlanHelpRequested Payload for weekly_plan.help_requested. A rep asked their lead for help on one commitment. It is its own type rather than another weekly_plan.updated. This is the one change somebody else is meant to act on. An automation notifying a lead subscribes to this event and not to every checkbox edit. The request text is not here. It stays on the row the lead opens, so what a rep says about being stuck does not ride a fan-out.
type PublicEventWeeklyPlanHelpRequested struct {
	CommitmentId openapi_types.UUID `json:"commitment_id"`
	OwnerUserId  openapi_types.UUID `json:"owner_user_id"`
	PlanId       openapi_types.UUID `json:"plan_id"`
}

// PublicEventWeeklyPlanUpdated Payload for weekly_plan.updated. A rep's plan for the week changed: opened, or a commitment added, edited or settled. The entity is the rep whose week it is, because the record belongs to them. The `changed_fields` list names what moved rather than carrying it. The labels and the help text stay on the row, since prose on two wires drifts.
type PublicEventWeeklyPlanUpdated struct {
	// ChangedFields Which parts of the plan moved — status, commitments.
	ChangedFields []string           `json:"changed_fields"`
	OwnerUserId   openapi_types.UUID `json:"owner_user_id"`
	PlanId        openapi_types.UUID `json:"plan_id"`
}

// SubscribableEventType The closed set of domain event types a webhook subscription may select — every subscribable event across the deal, offer, pipeline/stage, contact/company, lead, activities, consent/privacy, signals, ai voice and identity families. A subscription's event-type filter is validated against this set; an unlisted type cannot be subscribed to.
type SubscribableEventType string

